const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: 'y₁、y₂：振幅各 1.5（两曲线重合）' },
      { kind: 'text', payload: 'y₁ + y₂：振幅 3' },
      { kind: 'text', payload: '3' },
      { kind: 'text', payload: '1.5' },
      { kind: 'text', payload: '−1.5' },
      { kind: 'text', payload: '−3' },
      { kind: 'text', payload: 'O' },
      { kind: 'text', payload: 'x' }
    ];
  },
  render: function (input, metrics) {
    var vp = input.viewport || {};
    var w = vp.widthDu || 820;
    var h = vp.heightDu || 520;
    var left = 0.15 * w;
    var right = 0.90 * w;
    var cy = 0.55 * h;
    var s = Math.min(0.092 * h, 0.10 * w);
    var xEnd = Math.min(right + 20, w - 14);
    var P = Math.PI;

    function seg(x1, y1, x2, y2) { return [['M', x1, y1], ['L', x2, y2]]; }
    function px(u) { return left + (right - left) * (u / (4 * P)); }
    function sinePts(amp) {
      var pts = [], N = 320, i, u;
      for (i = 0; i <= N; i++) {
        u = 4 * P * i / N;
        pts.push([left + (right - left) * i / N, cy - amp * s * Math.sin(u)]);
      }
      return visualSdk.polyline(pts);
    }

    var gridCmds = [];
    var lv = [-3, -1.5, 1.5, 3];
    var i, yy;
    for (i = 0; i < lv.length; i++) {
      yy = cy - lv[i] * s;
      gridCmds = gridCmds.concat(seg(left, yy, right, yy));
    }

    var axisX = visualSdk.arrow(left - 16, cy, xEnd, cy, {});
    var axisY = visualSdk.arrow(left, cy + 3.3 * s, left, cy - 3.35 * s, {});

    var wave1 = sinePts(1.5);
    var wave2 = sinePts(1.5);
    var sumW = sinePts(3);
    var guide = seg(px(P / 2), cy, px(P / 2), cy - 3 * s);
    var marker = visualSdk.circle(px(P / 2), cy - 3 * s, 5);

    var ly1 = 0.075 * h, ly2 = 0.150 * h;
    var sw1 = seg(left, ly1, left + 26, ly1);
    var sw2 = seg(left, ly2, left + 26, ly2);

    return {
      schemaVersion: 1,
      sceneId: 'sine-superposition',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: w, height: h },
      paths: [
        { id: 'grid', commands: gridCmds },
        { id: 'axis', commands: axisX.concat(axisY) },
        { id: 'wave1', commands: wave1 },
        { id: 'wave2', commands: wave2 },
        { id: 'sum', commands: sumW },
        { id: 'guide', commands: guide },
        { id: 'marker', commands: marker },
        { id: 'sw1', commands: sw1 },
        { id: 'sw2', commands: sw2 }
      ],
      root: {
        type: 'group',
        children: [
          { type: 'path', pathId: 'grid', fill: '#CBD6E4', stroke: { width: 1, dash: [5, 5] } },
          { type: 'path', pathId: 'axis', fill: '#2B3A4F', stroke: { width: 2 } },
          { type: 'path', pathId: 'wave1', fill: '#8FB8E8', stroke: { width: 7, cap: 'round' } },
          { type: 'path', pathId: 'wave2', fill: '#1F6FD0', stroke: { width: 2.5, dash: [7, 6] } },
          { type: 'path', pathId: 'sum', fill: '#C0392B', stroke: { width: 3.5 } },
          { type: 'path', pathId: 'guide', fill: '#E2A29B', stroke: { width: 1.5, dash: [4, 4] } },
          { type: 'path', pathId: 'marker', fill: '#C0392B', stroke: { width: 2 } },
          { type: 'path', pathId: 'sw1', fill: '#8FB8E8', stroke: { width: 7, cap: 'round' } },
          { type: 'path', pathId: 'sw2', fill: '#C0392B', stroke: { width: 3.5 } },
          { type: 'label', contentId: metrics[0].contentId, anchor: { x: left + 34, y: ly1 }, hAlign: 'left', vAlign: 'middle', color: '#1F6FD0' },
          { type: 'label', contentId: metrics[1].contentId, anchor: { x: left + 34, y: ly2 }, hAlign: 'left', vAlign: 'middle', color: '#C0392B' },
          { type: 'label', contentId: metrics[2].contentId, anchor: { x: left - 10, y: cy - 3 * s }, hAlign: 'right', vAlign: 'middle', color: '#2B3A4F' },
          { type: 'label', contentId: metrics[3].contentId, anchor: { x: left - 10, y: cy - 1.5 * s }, hAlign: 'right', vAlign: 'middle', color: '#2B3A4F' },
          { type: 'label', contentId: metrics[4].contentId, anchor: { x: left - 10, y: cy + 1.5 * s }, hAlign: 'right', vAlign: 'middle', color: '#2B3A4F' },
          { type: 'label', contentId: metrics[5].contentId, anchor: { x: left - 10, y: cy + 3 * s }, hAlign: 'right', vAlign: 'middle', color: '#2B3A4F' },
          { type: 'label', contentId: metrics[6].contentId, anchor: { x: left - 10, y: cy + 10 }, hAlign: 'right', vAlign: 'top', color: '#2B3A4F' },
          { type: 'label', contentId: metrics[7].contentId, anchor: { x: xEnd - 8, y: cy - 16 }, hAlign: 'center', vAlign: 'bottom', color: '#2B3A4F' }
        ]
      }
    };
  }
};
